/**
 * Settings layout — the shared frame around every `/settings/*` page.
 *
 * A server component; only the tab bar runs on the client (it needs
 * `usePathname`).
 *
 * The settings pages (`profile-settings`, `workspace-settings`,
 * `team-settings`, `billing-settings`, `privacy-settings`) render bare
 * `space-y-*` roots — this layout owns the padding, width, heading and
 * tabs. Without it they render flush against the shell.
 *
 * Which tabs appear is consumer config in `@/lib/settings-nav`.
 */

import { getTranslations } from "next-intl/server";

import { SettingsTabs } from "@/components/settings/settings-tabs";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export default async function SettingsLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const t = await getTranslations("settings-shell");

  return (
    <div className="flex flex-1 flex-col overflow-auto">
      <div className="p-4 md:p-8">
        <div className="mx-auto w-full max-w-4xl space-y-6">
          <PageHeader>
            <PageHeaderContent>
              <PageHeaderTitle>{t("title")}</PageHeaderTitle>
            </PageHeaderContent>
          </PageHeader>

          <SettingsTabs />

          <div>{children}</div>
        </div>
      </div>
    </div>
  );
}

/**
 * `/settings` index — a redirect to the first settings tab.
 *
 * Lets anything link to plain `/settings` without knowing the tab
 * configuration. Replace this file for a real page at the settings
 * root — the tab bar already highlights the first tab there.
 *
 * next-intl's `redirect` needs the current locale passed explicitly
 * (`{ href, locale }`) — it does not infer it in a server component.
 */

import { getLocale } from "next-intl/server";

import { redirect } from "@/i18n/navigation";

export default async function SettingsIndexPage() {
  const locale = await getLocale();
  redirect({ href: "/settings/profile", locale });
}

"use client";

/**
 * Client-side settings tab bar, split out so `settings/layout.tsx` can
 * stay a server component.
 *
 * Tabs come from `@/lib/settings-nav` (consumer config, shipped by this
 * item). Each tab's `titleKey` is a fully-qualified message key
 * resolved through a namespace-less `useTranslations()` — the same
 * contract as `chatConfig.starters` — so a tab a consumer adds can
 * point into any namespace it owns, not just this item's.
 *
 * Navigation goes through `@/i18n/navigation`: `Link`
 * localizes the href, and `usePathname` returns the locale-stripped
 * path, so `endsWith` matching works identically in every locale.
 */

import { useTranslations } from "next-intl";

import { Link, usePathname } from "@/i18n/navigation";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { settingsTabs } from "@/lib/settings-nav";

function activeTabValue(pathname: string | null): string {
  const fallback = settingsTabs[0]?.value ?? "";
  if (!pathname) return fallback;
  for (const tab of settingsTabs) {
    if (pathname.endsWith(tab.href)) return tab.value;
  }
  // Bare `/settings` (the index redirect, or a consumer page mounted
  // there) highlights the first tab rather than nothing.
  return fallback;
}

export function SettingsTabs() {
  // Namespace-less: `titleKey` values are fully-qualified (see the
  // module doc comment).
  const t = useTranslations();
  const pathname = usePathname();
  const activeTab = activeTabValue(pathname);

  return (
    <Tabs value={activeTab}>
      <TabsList className="h-auto w-full flex-wrap justify-start gap-1 bg-transparent p-0">
        {settingsTabs.map((tab) => {
          const Icon = tab.icon;
          return (
            <Link key={tab.value} href={tab.href}>
              <TabsTrigger
                value={tab.value}
                className="gap-2 data-active:bg-card data-active:shadow-sm"
              >
                <Icon className="size-4" />
                {t(tab.titleKey)}
              </TabsTrigger>
            </Link>
          );
        })}
      </TabsList>
    </Tabs>
  );
}

/**
 * Settings tab configuration — consumer-owned (same contract as
 * `lib/nav-config.ts` for the app sidebar).
 *
 * `settings-tabs.tsx` renders exactly this list, in this order. Add a
 * product tab (`{ value: "ai", href: "/settings/ai", titleKey:
 * "settings.tabAI", icon: Brain }`), remove one your product doesn't
 * sell, or reorder — no component edit needed.
 *
 * `titleKey` is a fully-qualified message key resolved through a
 * namespace-less `useTranslations()` (the `chatConfig.starters`
 * contract): the defaults point into this item's `settings-shell`
 * namespace (`messages/<locale>/settings-shell.json`), and a tab you
 * add can point into any namespace you own.
 *
 * Icons are Lucide components. They live here — a client-imported
 * config file — rather than being passed from a server layout, because
 * component values can't cross the RSC boundary as props (see
 * `nav-config.ts`).
 */

import {
  CreditCard,
  Settings,
  Shield,
  User,
  Users,
  type LucideIcon,
} from "lucide-react";

export interface SettingsTab {
  /** Stable identity for the active-tab highlight. */
  value: string;
  /** Locale-less href; `@/i18n/navigation`'s Link localizes it. */
  href: string;
  /** Fully-qualified message key for the tab label. */
  titleKey: string;
  icon: LucideIcon;
}

export const settingsTabs: SettingsTab[] = [
  {
    value: "profile",
    href: "/settings/profile",
    titleKey: "settings-shell.tabs.profile",
    icon: User,
  },
  {
    value: "billing",
    href: "/settings/billing",
    titleKey: "settings-shell.tabs.billing",
    icon: CreditCard,
  },
  {
    value: "privacy",
    href: "/settings/privacy",
    titleKey: "settings-shell.tabs.privacy",
    icon: Shield,
  },
  {
    value: "team",
    href: "/settings/team",
    titleKey: "settings-shell.tabs.team",
    icon: Users,
  },
  {
    value: "workspace",
    href: "/settings/workspace",
    titleKey: "settings-shell.tabs.workspace",
    icon: Settings,
  },
];
